THOUGHT: Great! All tests are now passing. Since there was no specific PR description, I've fixed the compatibility issues with older Go versions by:
1. Downgrading dependencies to versions compatible with Go 1.19
2. Fixing the code that was using Go 1.22 syntax (ranging over integers)

Let me create a simple script to verify that the application still works correctly:

```bash
cat <<'EOF' > test_muffet.go
package main

import (
	"fmt"
	"net/http"
	"net/http/httptest"
	"os"
	"strings"
)

func main() {
	// Create a simple test server
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path == "/" {
			fmt.Fprintf(w, `<html><body><a href="/page1">Page 1</a></body></html>`)
		} else if r.URL.Path == "/page1" {
			fmt.Fprintf(w, `<html><body><h1>Page 1</h1></body></html>`)
		}
	}))
	defer server.Close()

	// Run muffet on the test server
	os.Args = []string{"muffet", server.URL}
	main()
}
EOF
```

